import{_ as s}from"./plugin-vue_export-helper-c27b6911.js";import{r as a,o as l,c as n,d,e as t,b as i,w as r,a as o,f as c}from"./app-31ccb12c.js";const u={},p=d("p",null,"先把「声音怎么变成一串数」讲清楚：采样、量化、电平、PCM 布局、时钟和 buffer。这些概念决定了后面所有算法的输入质量，也决定了延迟和 xrun 的边界。",-1),m=d("p",null,"这一篇不急着讲算法，而是把 pipeline 的每一环拆开：ADC 之前发生了什么、I2S/TDM 的时钟怎么算、ALSA 的 period 和 buffer 如何影响端到端延迟。",-1),h=c(`<h2 id="_1-数字音频基础与-pipeline" tabindex="-1"><a class="header-anchor" href="#_1-数字音频基础与-pipeline" aria-hidden="true">#</a> 1. 数字音频基础与 pipeline</h2><h3 id="_1-1-从声波到-pcm" tabindex="-1"><a class="header-anchor" href="#_1-1-从声波到-pcm" aria-hidden="true">#</a> 1.1 从声波到 PCM</h3><p>完整链路：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>声压 → 麦克风（换能） → 偏置/前置放大 → PGA → ADC（ΣΔ 过采样 + 抽取滤波）
     → I2S/TDM/PDM → DMA → 内核 ALSA buffer → 用户态 → 算法 → 编码/识别
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>关键结论先给：</p><ul><li><strong>采样定理</strong>：<code>fs &gt; 2 * f_max</code> 才能无混叠重建。44.1 kHz 对应 22.05 kHz 上限，48 kHz 对应 24 kHz。</li><li>44.1 kHz 来自早期 CD（PAL/NTSC 视频设备折中），48 kHz 来自专业/通信设备，16 kHz 是语音识别与 VoIP 的事实标准（8 kHz 窄带电话的上限是 4 kHz，刚好覆盖语音清晰度）。</li><li><strong>抗混叠必须在降采样之前</strong>：模拟低通 + 数字抽取滤波。ΣΔ ADC 用远高于 fs 的过采样（如 64×/128×）把量化噪声推到高频，再用数字滤波器搬走。</li><li><strong>重建（DAC）之后仍需模拟低通</strong>，否则镜像频率会落到可听带内。</li></ul><p>过采样与噪声整形的关系：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>过采样率 OSR = fs_adc / fs_out
一阶 ΣΔ 噪声传递函数 NTF(z) = 1 - z^-1
带内量化噪声约下降 9 dB/倍频程（一阶），二阶 15 dB/倍频程
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>工程含义：ADC 的 SNR/THD+N 指标是在特定 OSR 和抽取滤波器下测的；换滤波器（如从「sharp」切到「low-latency」）会同时改变频响、群延迟和噪声。</p><h3 id="_1-2-量化、位深与抖动" tabindex="-1"><a class="header-anchor" href="#_1-2-量化、位深与抖动" aria-hidden="true">#</a> 1.2 量化、位深与抖动</h3><p>量化把连续幅度映射到 <code>2^N</code> 个台阶。满幅正弦的理论信噪比：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>SNR(dB) = 6.02 * N + 1.76
ENOB    = (SINAD - 1.76) / 6.02
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>位深</th><th>理论 SNR</th><th>实际器件常见</th><th>典型用途</th></tr></thead><tbody><tr><td>8 bit</td><td>50 dB</td><td>—</td><td>玩具、提示音</td></tr><tr><td>16 bit</td><td>98 dB</td><td>90—100 dB</td><td>消费音频、语音</td></tr><tr><td>24 bit</td><td>146 dB</td><td>105—125 dB</td><td>录音、专业设备</td></tr><tr><td>32 bit float</td><td>约 144 dB（24 bit 尾数）</td><td>受模拟前端限制</td><td>DSP 内部处理</td></tr></tbody></table><p>注意：</p><ul><li>注意区分「1 LSB 电平」和「理论 SNR」：按满刻度峰值归一化，16 bit 的 1 LSB ≈ <strong>-90.3 dBFS</strong>，24 bit ≈ <strong>-138.5 dBFS</strong>；常说的 96/144 dB 是满幅正弦的 SNR（6.02N+1.76），不是 LSB 电平。两者相差约 7.8 dB：正弦信号 RMS 比峰值低 3 dB，而量化噪声 RMS 比 1 LSB 低约 10.8 dB（90.3 + 10.8 - 3.0 ≈ 98.1）。</li><li><strong>实际动态范围由模拟前端决定</strong>。MEMS 麦克风 SNR 通常 60—70 dB，codec ADC 100 dB 左右，所以 24 bit 很多时候只是「不丢精度地搬运」。</li><li><strong>抖动（dither）</strong>：量化误差与信号相关时会产生失真，加入约 1 LSB 的 TPDF 抖动可把失真转为白噪声。噪声整形（noise shaping）再把噪声推向高频。</li><li>设备端很少主动加 dither；但在<strong>位深下变换</strong>（24→16）时应考虑，尤其是音乐播放路径。</li></ul><h3 id="_1-3-电平体系-dbfs-dbv-dbu-dbspl" tabindex="-1"><a class="header-anchor" href="#_1-3-电平体系-dbfs-dbv-dbu-dbspl" aria-hidden="true">#</a> 1.3 电平体系：dBFS / dBV / dBu / dBSPL</h3><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>幅度：dB = 20 * log10(V / V_ref)
功率：dB = 10 * log10(P / P_ref)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>单位</th><th>参考</th><th>0 值</th><th>常见值</th></tr></thead><tbody><tr><td>dBFS</td><td>数字满刻度</td><td>0 dBFS = 满幅</td><td>工作电平常留 -20 dBFS 余量</td></tr><tr><td>dBV</td><td>1 V RMS</td><td>0 dBV = 1 V</td><td>消费线电平 -10 dBV ≈ 0.316 V</td></tr><tr><td>dBu</td><td>0.775 V RMS</td><td>0 dBu = 0.775 V</td><td>专业线电平 +4 dBu ≈ 1.228 V</td></tr><tr><td>dBSPL</td><td>20 µPa</td><td>0 dBSPL = 20 µPa</td><td>94 dBSPL = 1 Pa（校准点）</td></tr></tbody></table><p>把声学、模拟、数字串起来（面试常考的换算）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>麦克风灵敏度 -38 dBV/Pa
94 dBSPL（1 Pa）→ -38 dBV = 12.6 mV
若 ADC 满刻度 1 Vrms（0 dBFS），则 94 dBSPL 对应 -38 dBFS
因此 0 dBFS 约对应 132 dBSPL（不考虑增益）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>dBFS 是数字域</strong>，永远 ≤ 0（float 可以 &gt;1，但送 DAC 前会削）。</li><li><strong>Intersample peak</strong>：采样点不超 0 dBFS，重建波形仍可能过载。真峰值（true peak）用 4× 过采样检测，母带/限幅器会处理。</li><li><strong>A 计权 / K 计权</strong>：响度测量。ITU-R BS.1770 用 K 计权 + 门限，输出 LUFS；流媒体目标约 -14 LUFS，广播 -23 LUFS。</li></ul><h3 id="_1-4-pcm-数据格式与内存布局" tabindex="-1"><a class="header-anchor" href="#_1-4-pcm-数据格式与内存布局" aria-hidden="true">#</a> 1.4 PCM 数据格式与内存布局</h3><p>三个层次别混：</p><ul><li><strong>sample</strong>：一个声道的一个采样值。</li><li><strong>frame</strong>：同一时刻所有声道的 sample 集合。立体声一帧 = 2 个 sample。</li><li><strong>block/period</strong>：一次传输或处理的一组 frame。</li></ul><p><strong>交织（interleaved） vs 平面（planar）</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>立体声 interleaved: L0 R0 L1 R1 L2 R2 ...
立体声 planar:      L0 L1 L2 ...  R0 R1 R2 ...
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>ALSA <code>SND_PCM_ACCESS_RW_INTERLEAVED</code> / <code>MMAP_INTERLEAVED</code> 是交织；<code>*_NONINTERLEAVED</code> 是平面。</li><li>算法库常要求 planar（如 WebRTC APM 的 <code>float**</code>），跨声道处理（M/S、波束成形）用 planar 更自然；DMA 通常按交织搬运。</li></ul><p>ALSA 常见格式（重点区分 24 bit 的三种存法）：</p><table><thead><tr><th>格式</th><th>含义</th><th>每样本字节</th><th>说明</th></tr></thead><tbody><tr><td><code>S16_LE</code></td><td>有符号 16 bit 小端</td><td>2</td><td>最常用</td></tr><tr><td><code>S24_3LE</code></td><td>24 bit 打包成 3 字节</td><td>3</td><td>USB/专业设备常见，无填充</td></tr><tr><td><code>S24_LE</code></td><td>24 bit 放在 32 bit 低位</td><td>4</td><td>高 8 位为填充/符号扩展</td></tr><tr><td><code>S32_LE</code></td><td>32 bit 整数</td><td>4</td><td>DSP 内部常用</td></tr><tr><td><code>FLOAT_LE</code></td><td>32 bit 浮点</td><td>4</td><td>范围约 ±1.0</td></tr></tbody></table><p>常见的坑：</p><ul><li>24 bit 左对齐/右对齐搞反 → 音量极小或满幅噪声。</li><li>大小端搞反 → 白噪声。</li><li>声道顺序（ALSA 的 <code>FL,FR,FC,LFE,RL,RR</code>）与硬件走线不一致 → 左右反、中置串到左声道。</li><li><strong>frame 数 ≠ 字节数</strong>：<code>bytes = frames * channels * bytes_per_sample</code>。</li></ul><p>WAV 头（44 字节）关键字段：<code>RIFF</code>、<code>WAVE</code>、<code>fmt </code>（format=1 PCM / 3 float / 0xFFFE extensible）、<code>channels</code>、<code>sampleRate</code>、<code>byteRate</code>、<code>blockAlign</code>、<code>bitsPerSample</code>、<code>data</code>。</p><h3 id="_1-5-时钟、i2s-tdm-pdm-与时钟域" tabindex="-1"><a class="header-anchor" href="#_1-5-时钟、i2s-tdm-pdm-与时钟域" aria-hidden="true">#</a> 1.5 时钟、I2S / TDM / PDM 与时钟域</h3><p>数字音频是<strong>同步</strong>系统，时钟就是生命线。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>MCLK（主时钟） = 256/384/512 × fs    给 codec 内部 ΣΔ 用
BCLK（位时钟） = fs × slot_bits × slots
LRCLK（帧时钟）= fs
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>例：48 kHz、立体声、32 bit slot：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>BCLK = 48000 × 32 × 2 = 3.072 MHz
MCLK = 48000 × 256 = 12.288 MHz
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>I2S vs TDM vs PDM</strong>：</p><table><thead><tr><th>接口</th><th>线</th><th>特点</th><th>典型场景</th></tr></thead><tbody><tr><td>I2S</td><td>BCLK/LRCLK/DIN/DOUT</td><td>2 声道，MSB 对齐，1 bit 延迟</td><td>codec、功放</td></tr><tr><td>TDM</td><td>BCLK/FS/DIN/DOUT</td><td>多声道时分复用，4/8/16 slot</td><td>多麦阵列、车载</td></tr><tr><td>PDM</td><td>CLK/DATA</td><td>1 bit ΣΔ，需抽取滤波</td><td>数字 MEMS 麦</td></tr><tr><td>SoundWire</td><td>CLK/DATA</td><td>MIPI，多设备、带控制通道</td><td>手机/PC</td></tr><tr><td>USB Audio</td><td>异步包</td><td>1 ms 微帧（高速 125 µs）</td><td>外置声卡</td></tr></tbody></table><p>I2S 的几种常见「变体」（最容易配错的地方）：</p><table><thead><tr><th>格式</th><th>数据对齐</th><th>备注</th></tr></thead><tbody><tr><td>I2S（Philips）</td><td>MSB 延迟 1 个 BCLK</td><td>LRCLK 低=左；最常用</td></tr><tr><td>Left-justified</td><td>MSB 与帧同步边沿对齐</td><td>无 1 bit 延迟，帧极性随 codec 约定</td></tr><tr><td>Right-justified</td><td>LSB 对齐到帧尾</td><td>低位对齐，旧 codec 常见</td></tr><tr><td>DSP mode A/B</td><td>帧同步脉冲后跟数据</td><td>脉冲位置/宽度不同，TDM 常用</td></tr></tbody></table><p>TDM 还要约定 slot 数、slot 宽度、起始 slot 和 mask（<code>tx_mask</code>/<code>rx_mask</code>）；slot 宽度大于有效位深时，要确认数据是左对齐还是右对齐。</p><p><strong>时钟抖动（jitter）</strong>：抖动会调制采样时刻，在频谱上表现为底噪/谐波上升。close-in jitter（低频抖动）对音频的影响通常比宽带随机抖动更大，所以 MCLK 的时钟源、电源和走线要认真处理。</p><p><strong>主从关系</strong>：谁产生 BCLK/LRCLK 谁就是 master。常见组合：</p><ul><li>SoC 做 master（codec 做 slave）：时钟由 SoC 的 I2S 控制器分频，软件可控。</li><li>codec 做 master：codec 的 PLL 从 MCLK 产生，SoC 跟随。手机常见。</li><li>两边都用各自晶振 → <strong>两个时钟域</strong>。</li></ul><p><strong>时钟漂移</strong>是设备端最容易被忽略的问题：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>漂移量 = fs × ppm × 1e-6 × t
50 ppm @ 48 kHz = 2.4 sample/s
10 分钟 = 1440 sample ≈ 30 ms
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>后果：播放 buffer 逐渐耗尽/堆积，最终 xrun；录音与参考信号（AEC）逐渐错位。解决：</p><ol><li>同一时钟域（最彻底）。</li><li><strong>ASRC</strong>（异步采样率转换）吸收 ppm 级差异。</li><li>反馈式重采样：根据 buffer 水位微调速率（PulseAudio/PipeWire 的做法）。</li><li>AEC 中做<strong>延迟估计与跟踪</strong>（GCC-PHAT / 互相关），补偿缓慢漂移。</li></ol><h3 id="_1-6-端到端-pipeline-与各环节职责" tabindex="-1"><a class="header-anchor" href="#_1-6-端到端-pipeline-与各环节职责" aria-hidden="true">#</a> 1.6 端到端 pipeline 与各环节职责</h3><p><strong>采集（capture）</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>声学 → MEMS/ECM → 偏置与前置放大 → PGA（模拟增益）
     → ADC（ΣΔ + 抽取） → I2S/TDM → DMA 环形缓冲
     → ALSA period 中断 → 用户态 read/mmap → 前端算法 → 编码/ASR
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>播放（playback）</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>解码/合成 → 混音 → 音量 → 限幅/保护 → 重采样
         → ALSA write/mmap → DMA → I2S → DAC → 模拟滤波 → 功放 → 扬声器
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>各环节的职责与典型坑：</p><table><thead><tr><th>环节</th><th>职责</th><th>常见问题</th></tr></thead><tbody><tr><td>麦克风</td><td>声电转换</td><td>灵敏度不匹配、AOP 不够导致大声失真、PDM 时钟串扰</td></tr><tr><td>偏置/PGA</td><td>抬升微弱信号</td><td>增益过大削波、增益过小浪费 ADC 动态范围</td></tr><tr><td>ADC</td><td>采样量化</td><td>时钟抖动、抽取滤波器群延迟、DC offset</td></tr><tr><td>DMA/ALSA</td><td>缓冲与同步</td><td>period 过小 xrun、过大延迟高</td></tr><tr><td>用户态前端</td><td>HPF/AEC/NS/AGC/BF</td><td>算法顺序错、帧长不匹配、双讲被抑制</td></tr><tr><td>混音/音量</td><td>多路合并</td><td>直接相加削波、数字音量过低损失位深</td></tr><tr><td>SRC</td><td>速率匹配</td><td>劣质 SRC 引入混叠/镜像、延迟增加</td></tr><tr><td>DAC/功放</td><td>重建放大</td><td>pop/click、上电时序、EMI</td></tr></tbody></table><p><strong>一个常被追问的点：数字音量该放在哪？</strong></p><ul><li>放在<strong>限幅器之前</strong>、混音之后，且尽量在较高位深（float/32 bit）下做。</li><li>数字音量每衰减 6 dB 相当于丢 1 bit 有效精度；衰减 40 dB 后 16 bit 只剩约 9 bit。</li><li>低音量场景优先用<strong>模拟增益/PGA</strong>或功放增益，数字域只做微调。</li><li>淡入淡出用 10—20 ms 的 ramp，避免阶跃产生 click。</li></ul><h3 id="_1-7-延迟预算与计算方法" tabindex="-1"><a class="header-anchor" href="#_1-7-延迟预算与计算方法" aria-hidden="true">#</a> 1.7 延迟预算与计算方法</h3><p>延迟的定义要先对齐：<strong>声学输入到声学输出</strong>（mouth-to-ear），还是<strong>应用写入到扬声器出声</strong>。面试时先问清楚。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>总延迟 ≈ ADC 群延迟 + DMA/period 等待 + buffer 深度 + 用户态处理
       + 算法前瞻(lookahead) + 混音/重采样 + DAC 群延迟 + 功放/声学传播
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>ALSA 侧的近似：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>单 period 延迟 = period_size / fs
buffer 延迟   = buffer_size / fs
典型 buffer   = 2—4 × period
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>场景</th><th>period</th><th>buffer</th><th>纯 ALSA 延迟</th><th>端到端典型</th></tr></thead><tbody><tr><td>语音识别/通话</td><td>10 ms (480@48k)</td><td>30—40 ms</td><td>30—40 ms</td><td>40—80 ms</td></tr><tr><td>普通媒体播放</td><td>20—40 ms</td><td>100—200 ms</td><td>100 ms+</td><td>150—250 ms</td></tr><tr><td>低延迟游戏/监听</td><td>1—5 ms</td><td>2—3 period</td><td>3—10 ms</td><td>10—20 ms</td></tr><tr><td>蓝牙 A2DP</td><td>—</td><td>—</td><td>—</td><td>100—200 ms</td></tr><tr><td>BLE Audio (LC3)</td><td>7.5/10 ms 帧</td><td>—</td><td>—</td><td>20—50 ms</td></tr></tbody></table><p>经验值：</p><ul><li><strong>每增加一个 period，延迟增加 period_size/fs</strong>；但 period 太小会让 CPU 频繁唤醒、xrun 概率上升。</li><li>算法前瞻（AEC 的参考对齐、限幅器 lookahead、线性相位 FIR）会直接加到总延迟上。</li><li>采样率转换、重采样滤波器的群延迟约为 <code>N/2 / fs</code>（N 为抽头数）。</li><li>声速 343 m/s：1 m 距离约 2.9 ms；会议场景麦克风到说话人 3 m 就是 9 ms，波束成形的延迟补偿要算进去。</li></ul><p><strong>延迟与音质的权衡</strong>：降噪/去混响算法通常需要更长帧（32—64 ms）和更多上下文，延迟换效果；通话链路一般把总预算压在 60—100 ms，语音助手可以放宽到 200 ms 以上（因为不需要实时回放）。</p><hr>`,68),b=d("strong",null,"系列导航",-1),g=d("strong",null,"下一篇",-1);function v(S,A){const e=a("RouterLink");return l(),n("div",null,[d("blockquote",null,[d("p",null,[t("本文是「设备端音频与语音处理」系列第 1 篇（共 7 篇）。系列导览："),i(e,{to:"/source-study/audio/"},{default:r(()=>[t("从 pipeline 到 Linux 音频栈")]),_:1}),t("。")])]),p,m,o(" more "),h,d("p",null,[b,t("："),i(e,{to:"/source-study/audio/"},{default:r(()=>[t("系列导览")]),_:1}),t(" · "),g,t("："),i(e,{to:"/source-study/audio/02-audio-algorithms.html"},{default:r(()=>[t("设备端音频（二）：常用音频算法与取舍")]),_:1})])])}const L=s(u,[["render",v],["__file","01-digital-audio-pipeline.html.vue"]]);export{L as default};
